import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get_widgets(bp):
    return execute_tool('UMGToolSet.UMGToolSet.GetWidgets', json.dumps({'widgetBlueprint': bp}))['returnValue']

def add(bp, cls, name, parent=None):
    args = {'widgetBlueprint': bp, 'widgetClass': {'refPath': cls}, 'widgetDisplayName': name}
    if parent: args['parentWidget'] = parent
    return execute_tool('UMGToolSet.UMGToolSet.AddWidget', json.dumps(args))['returnValue']

def make_variable(bp, widget):
    return execute_tool('UMGToolSet.UMGToolSet.ToggleWidgetAsVariable', json.dumps({'widgetBlueprint': bp, 'widget': widget, 'bIsVariable': True}))['returnValue']

def list_props(obj):
    return execute_tool('editor_toolset.toolsets.object.ObjectTools.list_properties', json.dumps({'instance': obj}))['returnValue']

def setv(obj, values):
    ok = execute_tool('editor_toolset.toolsets.object.ObjectTools.set_properties', json.dumps({'instance': obj, 'values': json.dumps(values)}))['returnValue']
    if not ok: raise RuntimeError('property write failed')

def compile_widget(bp):
    if not execute_tool('UMGToolSet.UMGToolSet.CompileWidgetBlueprint', json.dumps({'widgetBlueprint': bp}))['returnValue']:
        raise RuntimeError('widget compile failed')

def build(path, fields):
    bp = load(path)
    info = get_widgets(bp)
    if not info.get('widgets'):
        root = add(bp, '/Script/UMG.VerticalBox', 'Root')['widget']
        for name, initial in fields:
            item = add(bp, '/Script/UMG.TextBlock', name, root)
            list_props(item['widget'])
            if item.get('slot'): list_props(item['slot'])
            setv(item['widget'], {'text': initial})
            make_variable(bp, item['widget'])
    compile_widget(bp)
    return bp

def run():
    inventory = build('/ExtractionOps/UI/W_ExtractionInventoryScreen', [('SlotsText','Raid Inventory'),('CommandText','Ready')])
    result = build('/ExtractionOps/UI/W_ExtractionResultScreen', [('ResultText','Run result pending')])
    paths = ['/ExtractionOps/UI/W_ExtractionInventoryScreen','/ExtractionOps/UI/W_ExtractionResultScreen']
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('widget save failed')
    return {'configured': paths}
